  container.innerHTML = '<div class="loader"><span class="spin">⟳</span> Cargando...</div>';

  try {
    const data = await api({ action: 'fetchAllWorkflows' });
    const synced = data.synced || []; 
    const n8nOnly = data.n8nOnly || []; 
    const ghOnly = data.githubOnly || [];

    document.getElementById('cnt-synced').textContent = synced.length;
    document.getElementById('cnt-n8n').textContent = n8nOnly.length;
    document.getElementById('cnt-gh').textContent = ghOnly.length;

    let htmlContent = '';
    if (synced.length) htmlContent += renderSection('✅ Sincronizados con GitHub', synced, 'synced', 'var(--green)', 'badge-green');
    if (n8nOnly.length) htmlContent += renderSection('⚠️ Solo en n8n (pendientes de sync)', n8nOnly, 'n8nOnly', 'var(--yellow)', 'badge-yellow');
    if (ghOnly.length) htmlContent += renderSection('📦 Solo en GitHub', ghOnly, 'ghOnly', 'var(--accent)', 'badge-blue');

    if (!htmlContent) htmlContent = '<div class="empty">No se encontraron workflows.</div>';
    container.innerHTML = htmlContent;
  } catch(e) { 
    container.innerHTML = '<div class="empty">❌ Error de conexión: ' + e.message + '</div>'; 
  }
}

function renderSection(title, items, type, color, badgeClass) {
  let rows = items.map(function(wf) { return renderRow(wf, type); }).join('');
  return '<div class="section-header"><div class="section-title" style="color:' + color + '">' + title + ' <span class="badge ' + badgeClass + '">' + items.length + '</span></div></div><div class="wf-list">' + rows + '</div>';
}

function renderRow(wf, type) {
  const active = wf.active;
  const dot = type === 'synced' ? 'var(--green)' : type === 'n8nOnly' ? 'var(--yellow)' : 'var(--accent)';
  const ghLink = wf.wf_url ? '<a class="github-link" href="' + wf.wf_url + '" target="_blank">↗ GitHub</a>' : '';

  const toggleHtml = wf.wf_id ? '<label class="toggle-switch" title="Activar/Desactivar"><input type="checkbox" ' + (active ? 'checked' : '') + ' onchange="toggleWf(\\'' + wf.wf_id + '\\',this.checked)"><span class="slider"></span></label>' : '';

  const syncBtn = (type === 'n8nOnly' || type === 'synced') && wf.wf_id ? '<button class="btn primary" onclick="syncWf(\\'' + wf.wf_id + '\\',\\'' + escapePath(wf.path) + '\\',\\'' + escapeStr(wf.name) + '\\')" title="Guardar en GitHub">⬆ Sync</button>' : '';

  const commitsBtn = wf.path ? '<button class="btn" onclick="viewCommits(\\'' + escapePath(wf.path) + '\\',\\'' + wf.wf_id + '\\',\\'' + escapeStr(wf.name) + '\\')" title="Ver historial">🕓 Commits</button>' : '';

  const importBtn = type === 'ghOnly' ? '<button class="btn" onclick="importWf(\\'' + escapePath(wf.path) + '\\',\\'' + wf.wf_id + '\\',\\'' + escapeStr(wf.name) + '\\')">⬇ Importar</button>' : '';

  return '<div class="wf-row"><div class="wf-status-dot" style="background:' + dot + '"></div><div class="wf-info"><div class="wf-name">' + (wf.name || wf.wf_id) + '</div><div class="wf-meta">ID: ' + (wf.wf_id || '—') + ' ' + ghLink + '</div></div><div class="wf-actions">' + toggleHtml + syncBtn + commitsBtn + importBtn + '</div></div>';
}

function escapePath(p) { return Array.isArray(p) ? (p[0]||'').split("'").join("\\\\'") : (p||'').split("'").join("\\\\'"); }
function escapeStr(s) { return (s||'').split("'").join("\\\\'"); }

async function toggleWf(id, active) {
  try {
    await api({ action: 'toggleStatus', workflowId: id, active: String(active) });
    toast(active ? 'Workflow activado' : 'Workflow desactivado');
  } catch(e) { toast('Error al cambiar estado', false); }
}

async function syncWf(id, path, name) {
  const msg = prompt('Mensaje del commit (opcional):', '[n8n Sync] ' + name + ' - Actualizado por ' + currentUser);
  if (msg === null) return;
  try {
    toast('Sincronizando...');
    await api({ action: 'syncWorkflow', workflowId: id, path: JSON.stringify([path]), commitMessage: msg || '' });
    toast('Guardado en GitHub ✓'); loadDashboard();
  } catch(e) { toast('Error al sincronizar', false); }
}

async function viewCommits(path, id, name) {
  document.getElementById('modal-title').textContent = '🕓 Commits — ' + name;
  document.getElementById('modal-body').innerHTML = '<div class="loader"><span class="spin">⟳</span> Cargando...</div>';
  document.getElementById('modal-commits').classList.add('open');
  try {
    const data = await api({ action: 'fetchCommits', workflowId: id, path: JSON.stringify([path]) });
    const commits = Array.isArray(data) ? data : [];
    if (!commits.length) { document.getElementById('modal-body').innerHTML = '<div class="empty">Sin commits registrados.</div>'; return; }

    let commitsHtml = '';
    for(let i=0; i<commits.length; i++) {
        let c = commits[i];
        let btnStr = c.sha ? '<button class="btn" style="margin-top:8px" onclick="restoreWf(\\'' + escapePath(path) + '\\',\\'' + id + '\\',\\'' + c.sha + '\\')">⏪ Restaurar esta versión</button>' : '';
        commitsHtml += '<div class="commit-item"><div class="commit-msg">' + c.message + '</div><div class="commit-meta">👤 ' + c.committer + ' · 🕓 ' + new Date(c.timestamp).toLocaleString('es') + ' · <a class="github-link" href="' + c.url + '" target="_blank">Ver commit ↗</a></div>' + btnStr + '</div>';
    }
    document.getElementById('modal-body').innerHTML = commitsHtml;
  } catch(e) { document.getElementById('modal-body').innerHTML = '<div class="empty">Error: ' + e.message + '</div>'; }
}

async function restoreWf(path, id, sha) {
  const action = confirm('¿Restaurar esta versión? Elige:\\nAceptar = Reemplazar workflow existente\\nCancelar = Crear workflow nuevo') ? 'replace' : 'import_new';
  closeModal();
  try {
    toast('Restaurando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha: sha, importAction: action });
    toast('Workflow restaurado ✓'); loadDashboard();
  } catch(e) { toast('Error al restaurar', false); }
}

async function importWf(path, id, name) {
  if (!confirm('¿Importar "' + name + '" desde GitHub?')) return;
  try {
    toast('Importando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha: '', importAction: 'import_new' });
    toast('Importado ✓'); loadDashboard();
  } catch(e) { toast('Error al importar', false); }
}

function closeModal() { document.getElementById('modal-commits').classList.remove('open'); }
document.getElementById('modal-commits').addEventListener('click', function(e) { if (e.target === e.currentTarget) closeModal(); });
